# kinlist.py -- the kin species kin.py writes: name -> its base, and what differs (kin.py's docstring)
M, B, S, O = "creatures/mammals/", "creatures/birds/", "creatures/sea/", "creatures/others/"

def bird(back, under, head=None, wing=None, tail=None, bill=None, leg=None, **more):
    """a songbird's (nb.py's) colours from a few: its back, its underside, its head, wing, tail -- each region's keys"""
    head, wing, tail = head or back, wing or back, tail or wing or back
    c = {k: back for k in ("back", "rump", "neck", "nape")}
    c.update({k: under for k in ("under", "vent", "thigh", "throat", "belly", "breast")})
    c.update({k: head for k in ("head", "crown", "cheek")})
    c.update({k: wing for k in ("cov", "covTip", "gcov", "gcovTip", "sec", "secTip", "tert", "tertTip", "wpad", "padC", "wing")})
    c.update({k: tail for k in ("tail", "tailTip", "prim", "primTip")})
    if bill: c.update(bill=bill, billLo=bill, beak=bill)
    if leg: c.update(leg=leg, foot=leg)
    c.update(more)
    return dict(colors=c, loose=True)
def kin(base, size, about, **k): return dict(base=base, size=size, about=about, **k)

